import struct
d=open('/private/tmp/claude-501/-Users-rod-build-stopwatch-screensaver/52b5f480-1b35-4f9b-b546-dbc5c1aff2c6/scratchpad/ad2/out/Flying_Toasters/ADgm_0.bin','rb').read()+b'\0\0\0\0'
w=lambda a: struct.unpack('>H',d[a:a+2])[0]
def jt(e):
    if w(e)==0x6000:
        disp=struct.unpack('>h',d[e+2:e+4])[0]; return e+2+disp
    return None
asm=open('/private/tmp/claude-501/-Users-rod-build-stopwatch-screensaver/52b5f480-1b35-4f9b-b546-dbc5c1aff2c6/scratchpad/ad2/ft.asm').read().splitlines()
# names: find dc.w lines after rts forming 8 ascii chars
names={}
lines=[(int(l[:5],16),l) for l in asm if len(l)>6 and l[5]==':']
cur=None
for i,(a,l) in enumerate(lines):
    if 'link.w a6' in l: cur=a
    if l.rstrip().endswith('rts') or 'jmp (a0)' in l:
        nxt=a+2
        s=d[nxt:nxt+8]
        if all(32<=b<127 for b in s) and cur is not None:
            names.setdefault(cur,s.decode())
nm=lambda t: f"{t:#x}({names.get(t,'?')})" if t is not None else '?'
jtab={}
for e in range(0x2e88,0x3070,2):
    if w(e)==0x6000:
        jtab[e]=jt(e)
for e,t in sorted(jtab.items()): print(hex(e),'->',nm(t))
for c in [0x2a9e,0x2ad8,0x2af4,0x2b08,0x2d6c,0x2d8e,0x2db8,0x2dde,0x2dfa,0x2e12]:
    size=w(c);n=w(c+2)+1
    pairs=[(w(c+4+4*i),w(c+6+4*i)) for i in range(n)]
    sup=w(c+4+4*n)
    print('class',hex(c),'size',hex(size),'super',hex(sup),[(nm(jtab.get(a)),hex(s)) for a,s in pairs])

